mapper.select:
SELECT ir.id, CAST(JSON_EXTRACT(r.normalized_payload, '$.features') AS CHAR) features
FROM inference_request ir
JOIN ingest_record r ON r.id=ir.ingest_record_id
JOIN ingest_batch ib ON ib.id=r.batch_id
JOIN model_version mv ON mv.id=ir.model_version_id
WHERE  AND ir.status='succeeded' AND mv.artifact_sha256=#{artifactSha256}
  AND ir.id > #{afterId}
ORDER BY ir.id
LIMIT #{limit}
